def cmd_verify(args: argparse.Namespace) -> int:
    """Offline light-client verification; no server contact is made."""
    from .light_client import verify_bundle

    try:
        if args.bundle == "-":
            bundle = json.loads(sys.stdin.read())
        else:
            with open(args.bundle, "r", encoding="utf-8") as fh:
                bundle = json.load(fh)
        with open(args.trust, "r", encoding="utf-8") as fh:
            trust = json.load(fh)
    except (OSError, ValueError, UnicodeDecodeError):
        # Unreadable or non-JSON inputs are reported in the same envelope as
        # every other verification failure.
        body = {"ok": False, "error": "input"}
    else:
        body = verify_bundle(bundle, trust)
    print(json.dumps(body, sort_keys=True, ensure_ascii=False))
    return 0 if body.get("ok") is True else 1


def cmd_verify_range(args: argparse.Namespace) -> int:
    """Offline verification of one exported incremental range delivery.

    Reads the export document (the ``GET /v1/forks/sync/range/export``
    response) from ``--export FILE`` or standard input (``-``), pins the
    expected anchor with ``--anchor-height``/``--anchor-hash`` and checks the
    source against the local trust document. Prints a single JSON line in the
    verifier's fixed key order and exits 0 on success, 1 on any failure;
    unreadable files, non-JSON input and illegal anchor arguments all report
    ``{"ok": false, "error": "input"}``.
    """
    from .light_client import verify_range_export

    try:
        if args.export == "-":
            document = json.loads(sys.stdin.read())
        else:
            with open(args.export, "r", encoding="utf-8") as fh:
                document = json.load(fh)
        with open(args.trust, "r", encoding="utf-8") as fh:
            trust = json.load(fh)
    except (OSError, ValueError, UnicodeDecodeError):
        # Unreadable or non-JSON inputs are reported in the same envelope as
        # every other verification failure.
        body = {"ok": False, "error": "input"}
    else:
        expected_anchor = _range_anchor_arg(args.anchor_height, args.anchor_hash)
        if expected_anchor is None:
            body = {"ok": False, "error": "input"}
        else:
            body = verify_range_export(document, expected_anchor, trust)
    print(json.dumps(body, sort_keys=False, ensure_ascii=False))
    return 0 if body.get("ok") is True else 1


def _range_anchor_arg(height_raw: str, hash_raw: str) -> dict | None:
    """Close the ``--anchor-height``/``--anchor-hash`` pair into an anchor.

    Both are validated as raw strings so an illegal value reports ``input``
    (exit 1) instead of an argparse usage error: the height must be a
    non-negative decimal integer and the hash 64 lowercase hex characters.
    """
    try:
        height = int(height_raw, 10)
    except ValueError:
        return None
    if height < 0 or not crypto.is_hex64(hash_raw):
        return None
    return {"height": height, "block_hash": hash_raw}


def cmd_verify_range_batch(args: argparse.Namespace) -> int:
    """Offline verification of a batch of exported incremental range pages.

    Reads a JSON array of range-export documents (the
    ``GET /v1/forks/sync/range/export`` responses, in delivery order) from
    ``--exports FILE`` or standard input (``-``), pins the first page's
    expected anchor with ``--anchor-height``/``--anchor-hash`` and checks
    every page against the local trust document. The pages must chain
    continuously (each page's anchor is the previous page's tip), tx_ids must
    be unique across the batch and a pending block may only appear on the last
    page. Prints one JSON line in the verifier's fixed key order and exits 0
    on success, 1 on any failure; unreadable files, non-JSON input and illegal
    anchor arguments all report ``{"ok": false, "error": "input"}``.
    """
    from .light_client import verify_range_exports

    try:
        if args.exports == "-":
            documents = json.loads(sys.stdin.read())
        else:
            with open(args.exports, "r", encoding="utf-8") as fh:
                documents = json.load(fh)
        with open(args.trust, "r", encoding="utf-8") as fh:
            trust = json.load(fh)
    except (OSError, ValueError, UnicodeDecodeError):
        # Unreadable or non-JSON inputs are reported in the same envelope as
        # every other verification failure.
        body = {"ok": False, "error": "input"}
    else:
        expected_anchor = _range_anchor_arg(args.anchor_height, args.anchor_hash)
        if expected_anchor is None:
            body = {"ok": False, "error": "input"}
        else:
            body = verify_range_exports(documents, expected_anchor, trust)
    print(json.dumps(body, sort_keys=False, ensure_ascii=False))
    return 0 if body.get("ok") is True else 1


def cmd_sync_plan(args: argparse.Namespace) -> int:
    """Read-only sync precheck: POST one sync-plan request document.

    ``FILE`` (or standard input when ``-``) supplies the JSON request body
    with the ordered keys ``locators``, ``tip`` and ``finalized``; it is
    POSTed verbatim to ``/v1/chain/sync-plan`` and the response is printed
    as one JSON line in the contract key order
    (``ok, ancestor, relation, pull, error``). An unreadable or non-JSON
    file prints ``{"ok": false, "error": "input"}`` and exits 1 without
    contacting the server; otherwise the exit code follows the response
    (0 only on 2xx).
    """
    try:
        if args.plan_file == "-":
            payload = json.loads(sys.stdin.read())
        else:
            with open(args.plan_file, "r", encoding="utf-8") as fh:
                payload = json.load(fh)
    except (OSError, ValueError, UnicodeDecodeError):
        # Unreadable or non-JSON input is reported in the same envelope as
        # the server's 400.
        body = {"ok": False, "error": "input"}
        print(json.dumps(body, sort_keys=False, ensure_ascii=False))
        return 1
    # The document is transmitted verbatim: the strict top-level key order
    # and every nested contract order must survive the round trip.
    status, body = _request(
        "POST",
        f"{args.base_url}/v1/chain/sync-plan",
        payload,
        sort_keys=False,
    )
    print(json.dumps(body, sort_keys=False, ensure_ascii=False))
    return 0 if 200 <= status < 300 else 1


def cmd_receipt_proofs_audit(args: argparse.Namespace) -> int:
    """Audit a batch of offline receipt-proof documents via the server.

    ``FILE`` (or standard input when ``-``) supplies the JSON array of
    ``receipt_proof`` documents; ``--expected-root`` pins the
    64-lowercase-hex Merkle root every document must recompute to. The
    batch is POSTed to ``/v1/transactions/receipt-proofs/audit`` and the
    response is printed as one JSON line in the contract key order
    (``ok, root, total, succeeded, errors, entries, digest``). A missing
    required argument, read, JSON or argument failure prints
    ``{"ok": false, "error": "input"}`` and exits 1 without contacting the
    server; otherwise the exit code is 0 only when the response is 2xx
    with ``ok`` true.
    """
    if not args.documents_file or not args.expected_root:
        # A missing FILE or --expected-root is an input error; answer before
        # reading any file or contacting the server.
        body = {"ok": False, "error": "input"}
        print(json.dumps(body, sort_keys=False, ensure_ascii=False))
        return 1
    try:
        if args.documents_file == "-":
            documents = json.loads(sys.stdin.read())
        else:
            with open(args.documents_file, "r", encoding="utf-8") as fh:
                documents = json.load(fh)
    except (OSError, ValueError, UnicodeDecodeError):
        # Unreadable or non-JSON input is an input error.
        body = {"ok": False, "error": "input"}
        print(json.dumps(body, sort_keys=False, ensure_ascii=False))
        return 1
    if not crypto.is_hex64(args.expected_root):
        body = {"ok": False, "error": "input"}
        print(json.dumps(body, sort_keys=False, ensure_ascii=False))
        return 1
    payload = {"documents": documents, "expected_root": args.expected_root}
    # The documents are transmitted verbatim: every receipt_proof document's
    # own contract key order must survive the round trip, so keys are kept in
    # insertion order (the top-level pair is already documents, expected_root).
    status, body = _request(
        "POST",
        f"{args.base_url}/v1/transactions/receipt-proofs/audit",
        payload,
        sort_keys=False,
    )
    print(json.dumps(body, sort_keys=False, ensure_ascii=False))
    return 0 if 200 <= status < 300 and body.get("ok") is True else 1


